def execute_with_backoff(call, max_retries=3, base_delay_ms=100, sleep=None):
    for attempt in range(max_retries + 1):
        try:
            return call()
        except Exception:
            if attempt == max_retries:
                raise
            sleep(base_delay_ms * 2 ** attempt)

