def default_hash(text):
    h = 0
    for ch in text:
        h = (h * 31 + ord(ch)) % 2 ** 32
    return h


class ConsistentHashRing:
    def __init__(self, hash_fn=default_hash):
        self.hash_fn = hash_fn
        self.ring = []  # sorted list of (hash, node)

    def add_node(self, node, vnodes=3):
        for i in range(vnodes):
            self.ring.append((self.hash_fn(f'{node}#{i}'), node))
        self.ring.sort()

    def remove_node(self, node):
        self.ring = [point for point in self.ring if point[1] != node]

    def get_node(self, key):
        if not self.ring:
            return None
        import bisect
        i = bisect.bisect_left([h for h, _ in self.ring], self.hash_fn(key))
        return self.ring[i % len(self.ring)][1]

class TtlCache:
    def __init__(self):
        self.store = {}  # key -> (value, expires_at)

    def get_or_fetch(self, key, fetch, now, ttl=60):
        hit = self.store.get(key)
        if hit and hit[1] > now:
            return hit[0]
        value = fetch(key)
        self.store[key] = (value, now + ttl)
        return value

    def get_many(self, keys, fetch, now, ttl=60):
        return [self.get_or_fetch(k, fetch, now, ttl) for k in keys]

import random


def ttl_with_jitter(base, max_jitter=10, rng=random):
    return base + rng.randrange(max_jitter)

class LockManager:
    def __init__(self):
        self.locks = {}  # resource -> {'lock_id', 'expires_at'}
        self.counter = 0

    def acquire(self, resource, now, ttl_ms=1000):
        held = self.locks.get(resource)
        if held and held['expires_at'] > now:
            return {'success': False}
        self.counter += 1
        lock_id = f'lock_{self.counter}'
        self.locks[resource] = {'lock_id': lock_id, 'expires_at': now + ttl_ms}
        return {'success': True, 'lock_id': lock_id, 'fencing_token': self.counter}

    def release(self, resource, lock_id):
        held = self.locks.get(resource)
        if held and held['lock_id'] == lock_id:
            del self.locks[resource]
            return True
        return False

def bully_election(node_ids, failed_leader):
    remaining = [n for n in node_ids if n != failed_leader]
    if not remaining:
        return {'leader': None, 'message': '', 'status': 'NO_ACTIVE_NODES'}
    leader = max(remaining)
    return {'leader': leader, 'message': f'COORDINATOR: Node {leader}', 'status': 'ELECTED'}

DIGITS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def time_prefix(ms):
    if ms == 0:
        return '0'
    out = ''
    while ms:
        ms, digit = divmod(ms, 36)
        out = DIGITS[digit] + out
    return out

def append_entries(log, prev_index, prev_term, entries):
    if prev_index >= 0 and (prev_index >= len(log) or log[prev_index]['term'] != prev_term):
        return {'success': False, 'reason': 'LOG_MISMATCH'}
    new_log = log[:prev_index + 1] + list(entries)
    return {'success': True, 'log': new_log, 'match_index': len(new_log) - 1}

def two_phase_commit(cohorts):
    votes = [c.prepare() for c in cohorts]
    if all(v == 'VOTE_COMMIT' for v in votes):
        for c in cohorts:
            c.commit()
        return {'status': 'GLOBAL_COMMITTED', 'votes': votes}
    for c in cohorts:
        c.abort()
    return {'status': 'GLOBAL_ABORTED', 'votes': votes}

def run_saga(steps):
    finished = []
    for step in steps:
        try:
            step['action']()
        except Exception as err:
            for done in reversed(finished):
                done['compensate']()
            return {'status': 'SAGA_COMPENSATED', 'failed_at': step['name'], 'error': str(err)}
        finished.append(step)
    return {'status': 'SAGA_COMPLETED'}

def assign_partitions(num_partitions, consumers):
    assignment = {c: [] for c in consumers}
    for p in range(num_partitions):
        assignment[consumers[p % len(consumers)]].append(p)
    return assignment

def route_to_partition(key, total):
    h = 0
    for ch in key:
        h = (h * 31 + ord(ch)) % 2 ** 32
    return h % total

def process_once(message_id, payload_hash, store, handler):
    seen = store.get(message_id)
    if seen:
        if seen['hash'] != payload_hash:
            return {'duplicate': True, 'error': 'PAYLOAD_MISMATCH'}
        return {'duplicate': True, 'result': seen['result']}
    result = handler()
    store[message_id] = {'hash': payload_hash, 'result': result}
    return {'duplicate': False, 'result': result}

def handle_message(msg, handler, dlq, max_attempts=3):
    try:
        return {'status': 'PROCESSED', 'result': handler(msg['payload'])}
    except Exception as err:
        msg['retry_count'] += 1
        if msg['retry_count'] >= max_attempts:
            dlq.append({'message': msg, 'error': str(err)})
            return {'status': 'ROUTED_TO_DLQ'}
        return {'status': 'RETRY_SCHEDULED', 'attempt': msg['retry_count'] + 1}

def run_transaction(event, store, steps, dlq):
    if event['key'] in store:
        return {'status': 'DUPLICATE_DROPPED'}
    finished = []
    for step in steps:
        try:
            step['execute']()
        except Exception as err:
            for done in reversed(finished):
                done['compensate']()
            dlq.append({'event': event, 'error': str(err)})
            return {'status': 'FAILED_COMPENSATED'}
        finished.append(step)
    store[event['key']] = 'COMMITTED'
    return {'status': 'COMMITTED'}

def compare_vector_clocks(a, b):
    nodes = set(a) | set(b)
    a_ahead = any(a.get(n, 0) > b.get(n, 0) for n in nodes)
    b_ahead = any(b.get(n, 0) > a.get(n, 0) for n in nodes)
    if a_ahead and b_ahead:
        return 'CONCURRENT'
    if b_ahead:
        return 'A_BEFORE_B'
    if a_ahead:
        return 'B_BEFORE_A'
    return 'EQUAL'

class PNCounter:
    def __init__(self, node_id):
        self.node_id = node_id
        self.p = {}  # node -> total added by that node
        self.n = {}  # node -> total subtracted by that node

    def increment(self, v=1):
        self.p[self.node_id] = self.p.get(self.node_id, 0) + v

    def decrement(self, v=1):
        self.n[self.node_id] = self.n.get(self.node_id, 0) + v

    def value(self):
        return sum(self.p.values()) - sum(self.n.values())

    def merge(self, other):
        for mine, theirs in ((self.p, other.p), (self.n, other.n)):
            for node in set(mine) | set(theirs):
                mine[node] = max(mine.get(node, 0), theirs.get(node, 0))

def shard_for_customer(customer_id, directory, num_shards=4):
    if customer_id in directory:
        return directory[customer_id]
    h = 0
    for ch in customer_id:
        h = (h * 31 + ord(ch)) % 2 ** 32
    return f'shard_{h % num_shards}'

def range_shard(user_id):
    if user_id <= 1000:
        return 'shard_1'
    if user_id <= 2000:
        return 'shard_2'
    return 'shard_3'

def route_query(op, session, now, replicas):
    if op == 'WRITE':
        session['last_write'] = now
        return 'MASTER'
    last = session.get('last_write')
    if last is not None and now - last < 5000:
        return 'MASTER'
    reads = session.get('reads', 0)
    session['reads'] = reads + 1
    return replicas[reads % len(replicas)]

class CircuitOpenError(Exception):
    pass


class CircuitBreaker:
    def __init__(self, threshold=3, reset_timeout_ms=500):
        self.state = 'CLOSED'
        self.failures = 0
        self.threshold = threshold
        self.reset_timeout_ms = reset_timeout_ms
        self.opened_at = 0

    def call(self, fn, now):
        if self.state == 'OPEN':
            if now - self.opened_at < self.reset_timeout_ms:
                raise CircuitOpenError('CIRCUIT_OPEN')
            self.state = 'HALF_OPEN'
        try:
            result = fn()
        except Exception:
            self.failures += 1
            if self.state == 'HALF_OPEN' or self.failures >= self.threshold:
                self.state = 'OPEN'
                self.opened_at = now
            raise
        self.failures = 0
        self.state = 'CLOSED'
        return result

