def handle_gateway(client_id, is_allowed, breaker_call, backend):
    if not is_allowed(client_id):
        return {'status': 429}
    try:
        return {'status': 200, 'data': breaker_call(backend)}
    except CircuitOpenError:
        return {'status': 503}
    except Exception as err:
        return {'status': 500, 'error': str(err)}

def swim_probe(target, ping, peers, k=2):
    try:
        ping(target)
        return {'status': 'ALIVE', 'method': 'DIRECT'}
    except TimeoutError:
        pass
    for peer in [p for p in peers if p != target][:k]:
        try:
            ping(target, via=peer)
            return {'status': 'ALIVE', 'method': 'INDIRECT'}
        except TimeoutError:
            continue
    return {'status': 'SUSPECT', 'method': 'INDIRECT'}

class WeightedRoundRobin:
    def __init__(self):
        self.servers = []  # dicts: {'id', 'weight', 'current'}

    def add_server(self, server_id, weight):
        self.servers.append({'id': server_id, 'weight': weight, 'current': 0})

    def next_server(self):
        for s in self.servers:
            s['current'] += s['weight']
        best = max(self.servers, key=lambda s: s['current'])
        best['current'] -= sum(s['weight'] for s in self.servers)
        return best['id']

class ServiceRegistry:
    def __init__(self):
        self.services = {}  # name -> {instance_id: {'url', 'ttl_ms', 'expires_at'}}

    def register(self, name, instance_id, url, now, ttl_ms=5000):
        self.services.setdefault(name, {})[instance_id] = {'url': url, 'ttl_ms': ttl_ms, 'expires_at': now + ttl_ms}

    def heartbeat(self, name, instance_id, now):
        inst = self.services.get(name, {}).get(instance_id)
        if inst is None:
            return False
        inst['expires_at'] = now + inst['ttl_ms']
        return True

    def healthy(self, name, now):
        group = self.services.get(name, {})
        for instance_id in [i for i, inst in group.items() if inst['expires_at'] <= now]:
            del group[instance_id]
        return [{'id': i, 'url': inst['url']} for i, inst in group.items()]

def aggregate_profile(user_id, get_user, get_orders, get_reviews):
    user = get_user(user_id)
    orders = get_orders(user_id)
    try:
        reviews_count, partial = len(get_reviews(user_id)), False
    except Exception:
        reviews_count, partial = None, True
    return {
        'user_id': user['id'],
        'name': user['name'],
        'recent_orders': orders[:3],
        'orders_count': len(orders),
        'reviews_count': reviews_count,
        'partial': partial,
    }

def child_span(traceparent, name, new_span_id, new_trace_id):
    parts = (traceparent or '').split('-')
    if len(parts) == 4:
        trace_id, parent_id = parts[1], parts[2]
    else:
        trace_id, parent_id = new_trace_id, None
    return {
        'name': name,
        'trace_id': trace_id,
        'parent_id': parent_id,
        'span_id': new_span_id,
        'traceparent': f'00-{trace_id}-{new_span_id}-01',
    }

import re


def is_valid_traceparent(header):
    return re.fullmatch(r'00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}', header) is not None

def audit_linearizability(reads, writes):
    stale = []
    for r in reads:
        before = [w for w in writes if w['completed_at'] <= r['started_at']]
        if before and r['observed'] != max(before, key=lambda w: w['completed_at'])['value']:
            stale.append(r)
    return {'linearizable': not stale, 'stale_reads': stale}

LEVELS = {
    'STRONG': 'Linearizable (global real-time order)',
    'CAUSAL': 'Causal (cause before effect)',
    'EVENTUAL': 'Eventual (replicas converge)',
}


def consistency_level(mode):
    if mode not in LEVELS:
        raise ValueError(mode)
    return LEVELS[mode]

import re


def evaluate_edge_cache(cache_control, age):
    def seconds(name):
        m = re.search(name + r'=(\d+)', cache_control)
        return int(m.group(1)) if m else 0

    max_age = seconds(r'(?<![-\w])max-age')
    swr = seconds('stale-while-revalidate')
    if age <= max_age:
        return {'status': 'FRESH', 'revalidate': False}
    if age <= max_age + swr:
        return {'status': 'STALE_REVALIDATING', 'revalidate': True}
    return {'status': 'EXPIRED', 'revalidate': False}

def dr_compliance(actual_rpo, actual_rto, target_rpo, target_rto):
    rpo_ok, rto_ok = actual_rpo <= target_rpo, actual_rto <= target_rto
    return {
        'compliant': rpo_ok and rto_ok,
        'rpo': 'OK' if rpo_ok else 'BREACHED',
        'rto': 'OK' if rto_ok else 'BREACHED',
        'grade': 'TIER_1' if rpo_ok and rto_ok else 'FAILED',
    }

def execute_trade(order, services):
    if not services['is_allowed'](order['account']):
        return {'success': False, 'error': 'RATE_LIMITED'}
    lock = services['acquire'](order['account'])
    if not lock['success']:
        return {'success': False, 'error': 'ACCOUNT_LOCKED'}
    try:
        services['replicate']({'order_id': order['order_id'], 'amount': order['amount'], 'fencing_token': lock['fencing_token']})
        receipt = services['commit'](order)
        return {'success': True, 'receipt': receipt, 'fencing_token': lock['fencing_token']}
    except Exception as err:
        return {'success': False, 'error': str(err)}
    finally:
        services['release'](order['account'], lock['lock_id'])

def audit_distributed_capstone(checks):
    failed = sorted(name for name, ok in checks.items() if not ok)
    return {'passed': len(checks) - len(failed), 'failed': failed, 'certified': bool(checks) and not failed}
